// -------------------------------------------------------------------------------------------------
// Timings (docs/protocol/frame.md and docs/protocol/console.md)

/** A node sends a HELLO every period, give or take the jitter at random. */
export const HELLO_PERIOD_MILLISECONDS = 10000;
export const HELLO_JITTER_MILLISECONDS = 2000;

/** The first HELLO after a boot or a suspension leaves within this window. */
export const FIRST_HELLO_MINIMUM_DELAY_MILLISECONDS = 1000;
export const FIRST_HELLO_MAXIMUM_DELAY_MILLISECONDS = 3000;

/**
 * A neighbor leaves the table when no packet of it arrives for this long; see isNeighborExpired.
 */
export const NEIGHBOR_EXPIRY_MILLISECONDS = 60000;

/**
 * True when a neighbor last heard `elapsedMilliseconds` ago has expired, from
 * NEIGHBOR_EXPIRY_MILLISECONDS on, as in the firmware.
 */
export function isNeighborExpired(elapsedMilliseconds: number): boolean {
  return elapsedMilliseconds >= NEIGHBOR_EXPIRY_MILLISECONDS;
}

/** Limits, in seconds, of the hold of the HELLO messages that presence off accepts. */
export const MINIMUM_PRESENCE_HOLD_SECONDS = 1;
export const MAXIMUM_PRESENCE_HOLD_SECONDS = 3600;

/** Margin of the echo_lost and run_end deadlines; see the functions below. */
export const RESPONSE_MARGIN_MILLISECONDS = 1000;

/**
 * Time from the start of an echo request on the air until the requester reports echo_lost: twice
 * the time on air of the request in whole milliseconds, rounded up, plus the margin
 * (RESPONSE_MARGIN_MILLISECONDS), as the firmware computes it.
 */
export function echoLossDeadlineMilliseconds(requestTimeOnAirMicroseconds: number): number {
  return 2 * Math.ceil(requestTimeOnAirMicroseconds / 1000) + RESPONSE_MARGIN_MILLISECONDS;
}

/**
 * Time from a TEST packet of a run until the receiver ends the run with run_end when no other
 * arrives: twice the sum of the interval and the time on air of the packet in whole milliseconds,
 * rounded up, plus the margin (RESPONSE_MARGIN_MILLISECONDS), as the firmware computes it.
 */
export function runReceptionDeadlineMilliseconds(
  intervalMilliseconds: number,
  packetTimeOnAirMicroseconds: number,
): number {
  return (
    2 * (intervalMilliseconds + Math.ceil(packetTimeOnAirMicroseconds / 1000)) +
    RESPONSE_MARGIN_MILLISECONDS
  );
}

/** Added to the burst end and to the report repeat deadlines. */
export const TRANSFER_MARGIN_MILLISECONDS = 500;
